<section class="page-banner"><div class="container"><div class="section-label">STAY IN THE LOOP</div><h1>Notifications</h1><p>Updates about your clubs, event registrations, and account.</p></div></section><section class="section container narrow"><form action="<?= e(url('notifications/read')) ?>" method="post" class="right-align"><?= csrf_field() ?><button class="btn btn-outline" type="submit">Mark all as read</button></form><div class="card panel"><?php if($items): ?><?php foreach($items as $n): ?><div class="notification-row <?= !$n['is_read']?'unread':'' ?>"><div><strong><?= e($n['title']) ?></strong><p><?= e($n['message']) ?></p><small><?= e(pretty_date($n['created_at'])) ?></small><?php if($n['link']): ?><div><a class="inline-arrow" href="<?= e(message_url($n['link'])) ?>">View related page →</a></div><?php endif; ?></div><?php if(!$n['is_read']): ?><form method="post" action="<?= e(url('notifications/read')) ?>"><?= csrf_field() ?><input name="id" type="hidden" value="<?= (int)$n['id'] ?>"><button class="btn btn-outline btn-sm" type="submit">Mark read</button></form><?php endif; ?></div><?php endforeach; ?><?php else: ?><div class="empty-state">You're all caught up.</div><?php endif; ?></div></section>
